package cn.zhuatech.rpa.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class BotProductionReleaseServiceTest{private final BotProductionReleaseService service=new BotProductionReleaseService();@Test void deploysGovernedBot(){var r=service.assess(new BotProductionReleaseService.Request("B1",true,true,95,true,true,true,true,true,1));assertThat(r.decision()).isEqualTo(BotProductionReleaseService.Decision.DEPLOY);}@Test void blocksSecurityAndTestFailures(){var r=service.assess(new BotProductionReleaseService.Request("B2",false,false,50,false,false,false,true,true,1));assertThat(r.blockers()).hasSize(6);}@Test void pilotsOperationalRisk(){var r=service.assess(new BotProductionReleaseService.Request("B3",true,true,95,true,true,true,false,false,10));assertThat(r.actions()).hasSize(3);}}
